import {
  MAX_ELAPSED_MS,
  MAX_MOVES,
  MAX_SNAPSHOT_BYTES,
  MISMATCH_DURATION_MS,
  SNAPSHOT_VERSION,
} from './constants.ts';
import { createGame, isWon } from './transitions.ts';
import type { GameState, Selection } from './types.ts';

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function hasExactKeys(value: Record<string, unknown>, expected: readonly string[]): boolean {
  const keys = Object.keys(value);
  return keys.length === expected.length && expected.every((key) => Object.hasOwn(value, key));
}

function isSafeCount(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
}

function selectionFrom(value: unknown, state: GameState, matched: ReadonlySet<number>): Selection | null {
  if (!isRecord(value) || typeof value.kind !== 'string') return null;
  const length = state.board.deck.length;
  const validUnmatched = (index: unknown): index is number =>
    isSafeCount(index) && index < length && !matched.has(index);
  if (value.kind === 'closed' && hasExactKeys(value, ['kind'])) return { kind: 'closed' };
  if (value.kind === 'one' && hasExactKeys(value, ['kind', 'index']) && validUnmatched(value.index)) {
    return { kind: 'one', index: value.index };
  }
  if (
    value.kind === 'mismatch' &&
    hasExactKeys(value, ['kind', 'first', 'second', 'remainingMs']) &&
    validUnmatched(value.first) && validUnmatched(value.second) &&
    value.first !== value.second &&
    state.board.deck[value.first] !== state.board.deck[value.second] &&
    isSafeCount(value.remainingMs) &&
    value.remainingMs >= 1 &&
    value.remainingMs <= MISMATCH_DURATION_MS
  ) {
    return { kind: 'mismatch', first: value.first, second: value.second, remainingMs: value.remainingMs };
  }
  return null;
}

function matchedPositions(value: unknown, state: GameState): readonly number[] | null {
  if (!Array.isArray(value)) return null;
  const positions = new Set<number>();
  const faceCounts = new Map<number, number>();
  for (const index of value as unknown[]) {
    if (!isSafeCount(index) || index >= state.board.deck.length || positions.has(index)) return null;
    const face = state.board.deck[index];
    if (face === undefined) return null;
    positions.add(index);
    faceCounts.set(face, (faceCounts.get(face) ?? 0) + 1);
  }
  if ([...faceCounts.values()].some((count) => count !== 2)) return null;
  return [...positions];
}

export function decodeSnapshot(text: string): GameState | null {
  if (new TextEncoder().encode(text).byteLength > MAX_SNAPSHOT_BYTES) return null;
  let value: unknown;
  try {
    value = JSON.parse(text) as unknown;
  } catch {
    return null;
  }
  if (!isRecord(value) || !hasExactKeys(value, ['version', 'boardCode', 'matched', 'selection', 'moves', 'elapsedMs', 'started'])) {
    return null;
  }
  if (value.version !== SNAPSHOT_VERSION || typeof value.boardCode !== 'string') return null;
  const initial = createGame(value.boardCode);
  if (initial === null) return null;
  const matched = matchedPositions(value.matched, initial);
  if (matched === null || !isSafeCount(value.moves) || value.moves > MAX_MOVES) return null;
  if (!isSafeCount(value.elapsedMs) || value.elapsedMs > MAX_ELAPSED_MS || typeof value.started !== 'boolean') return null;
  const matchedSet = new Set(matched);
  const selection = selectionFrom(value.selection, initial, matchedSet);
  if (selection === null) return null;
  const matchedPairs = matched.length / 2;
  const completed = matched.length === initial.board.deck.length;
  if (completed && selection.kind !== 'closed') return null;
  if (value.moves < matchedPairs || (selection.kind === 'mismatch' && value.moves < matchedPairs + 1)) return null;
  if (!value.started && (value.moves !== 0 || value.elapsedMs !== 0 || matched.length !== 0 || selection.kind !== 'closed')) return null;
  if (value.started && value.moves === 0 && selection.kind !== 'one') return null;
  return Object.freeze({
    ...initial,
    matched: Object.freeze(matched),
    selection: Object.freeze(selection),
    moves: value.moves,
    elapsedMs: value.elapsedMs,
    started: value.started,
  });
}

export function encodeSnapshot(state: GameState): string {
  const selection = state.selection.kind === 'mismatch'
    ? {
        kind: 'mismatch',
        first: state.selection.first,
        second: state.selection.second,
        remainingMs: Math.max(1, Math.floor(state.selection.remainingMs)),
      }
    : state.selection;
  const snapshot = {
    version: SNAPSHOT_VERSION,
    boardCode: state.board.code,
    matched: [...state.matched],
    selection,
    moves: state.moves,
    elapsedMs: Math.floor(state.elapsedMs),
    started: state.started,
  };
  return JSON.stringify(snapshot);
}

export function isCompletedSnapshot(state: GameState): boolean {
  return isWon(state);
}
import {
  MAX_ELAPSED_MS,
  MAX_REPLAY_ACTIONS,
  MAX_REPLAY_BYTES,
  REPLAY_VERSION,
} from './constants.ts';
import { createGame } from './transitions.ts';
import { activateCard, advanceGame } from './transitions.ts';
import type { GameState } from './types.ts';

type ReplayAction = Readonly<{ atMs: number; index: number }>;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function exactKeys(value: Record<string, unknown>, expected: readonly string[]): boolean {
  const keys = Object.keys(value);
  return keys.length === expected.length && expected.every((key) => Object.hasOwn(value, key));
}

function safeTime(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
}

function parseReplay(text: string): Readonly<{ state: GameState; actions: readonly ReplayAction[]; endMs: number }> | null {
  if (new TextEncoder().encode(text).byteLength > MAX_REPLAY_BYTES) return null;
  let value: unknown;
  try {
    value = JSON.parse(text) as unknown;
  } catch {
    return null;
  }
  if (!isRecord(value) || !exactKeys(value, ['version', 'boardCode', 'actions', 'endMs'])) return null;
  if (value.version !== REPLAY_VERSION || typeof value.boardCode !== 'string' || !Array.isArray(value.actions)) return null;
  if (value.actions.length > MAX_REPLAY_ACTIONS || !safeTime(value.endMs)) return null;
  const state = createGame(value.boardCode);
  if (state === null) return null;
  const actions: ReplayAction[] = [];
  let previousTime = 0;
  for (const action of value.actions as unknown[]) {
    if (!isRecord(action) || !exactKeys(action, ['atMs', 'index'])) return null;
    if (!safeTime(action.atMs) || !safeTime(action.index) || action.index >= state.board.deck.length) return null;
    if (action.atMs < previousTime || action.atMs > value.endMs) return null;
    actions.push({ atMs: action.atMs, index: action.index });
    previousTime = action.atMs;
  }
  return { state, actions, endMs: value.endMs };
}

export function replayGame(text: string): GameState | null {
  const replay = parseReplay(text);
  if (replay === null) return null;
  let state = replay.state;
  let cursor = 0;
  for (const action of replay.actions) {
    const delta = action.atMs - cursor;
    state = advanceGame(state, delta);
    state = activateCard(state, action.index);
    cursor = action.atMs;
  }
  state = advanceGame(state, replay.endMs - cursor);
  if (state.elapsedMs > MAX_ELAPSED_MS) return null;
  return state;
}
import { readFile } from 'node:fs/promises';
import { encodeSnapshot } from '../src/game/snapshot.ts';
import { replayGame } from '../src/game/replay.ts';

const path = process.argv[2];
if (path === undefined || process.argv.length !== 3) {
  process.stderr.write('Usage: npm run --silent replay -- PATH\n');
  process.exitCode = 1;
} else {
  try {
    const text = await readFile(path, 'utf8');
    const state = replayGame(text);
    if (state === null) throw new Error('Invalid replay.');
    process.stdout.write(`${encodeSnapshot(state)}\n`);
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unable to read replay.';
    process.stderr.write(`${message}\n`);
    process.exitCode = 1;
  }
}

import type { BoardSize } from './constants.ts';

export type Board = Readonly<{
  code: string;
  size: BoardSize;
  deck: readonly number[];
}>;

export type Selection =
  | Readonly<{ kind: 'closed' }>
  | Readonly<{ kind: 'one'; index: number }>
  | Readonly<{
      kind: 'mismatch';
      first: number;
      second: number;
      remainingMs: number;
    }>;

export type GameState = Readonly<{
  board: Board;
  matched: readonly number[];
  selection: Selection;
  moves: number;
  elapsedMs: number;
  started: boolean;
}>;

export type BoardCode = Readonly<{ size: BoardSize; seed: number; code: string }>;
export const BOARD_SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
export const BOARD_CODE_VERSION = 1;
export const SNAPSHOT_VERSION = 1;
export const REPLAY_VERSION = 1;
export const MISMATCH_DURATION_MS = 800;
export const MAX_ELAPSED_MS = 359_999_999;
export const MAX_MOVES = 999_999;
export const MAX_BOARD_SEED = 2_147_483_646;
export const MAX_SNAPSHOT_BYTES = 65_536;
export const MAX_REPLAY_BYTES = 1_048_576;
export const MAX_REPLAY_ACTIONS = 10_000;

export type BoardSize = (typeof BOARD_SIZES)[number];
import { BOARD_SIZES, MAX_BOARD_SEED, type BoardSize } from './constants.ts';
import type { BoardCode } from './types.ts';

function isBoardSize(value: number): value is BoardSize {
  return BOARD_SIZES.some((size) => size === value);
}

export function parseBoardCode(value: string): BoardCode | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(value);
  if (match === null) return null;
  const size = Number(match[1]);
  const seed = Number(match[2]);
  if (!isBoardSize(size) || !Number.isSafeInteger(seed) || seed > MAX_BOARD_SEED) {
    return null;
  }
  return { code: value, size: size as BoardSize, seed };
}
import type { BoardCode } from './types.ts';

const PARK_MILLER_MODULUS = 2_147_483_647;
const PARK_MILLER_MULTIPLIER = 16_807;
const UNIFORM_SAMPLE_COUNT = PARK_MILLER_MODULUS - 1;

export function generateDeck({ size, seed }: BoardCode): readonly number[] {
  let state = seed;
  const nextState = (): number => {
    state = (state * PARK_MILLER_MULTIPLIER) % PARK_MILLER_MODULUS;
    return state;
  };
  const deck = Array.from({ length: size * size }, (_, position) => Math.floor(position / 2));
  for (let index = deck.length - 1; index > 0; index -= 1) {
    const choices = index + 1;
    const limit = Math.floor(UNIFORM_SAMPLE_COUNT / choices) * choices;
    let sample = nextState() - 1;
    while (sample >= limit) sample = nextState() - 1;
    const target = sample % choices;
    const current = deck[index];
    const other = deck[target];
    if (current === undefined || other === undefined) throw new Error('Invalid shuffle position.');
    deck[index] = other;
    deck[target] = current;
  }
  return Object.freeze(deck);
}
import { MAX_ELAPSED_MS, MAX_MOVES, MISMATCH_DURATION_MS } from './constants.ts';
import { parseBoardCode } from './boardCode.ts';
import { generateDeck } from './deck.ts';
import type { Board, GameState, Selection } from './types.ts';

const CLOSED: Selection = Object.freeze({ kind: 'closed' });

export function createGame(boardCode: string): GameState | null {
  const parsed = parseBoardCode(boardCode);
  if (parsed === null) return null;
  const board: Board = Object.freeze({ code: parsed.code, size: parsed.size, deck: generateDeck(parsed) });
  return Object.freeze({ board, matched: Object.freeze([]), selection: CLOSED, moves: 0, elapsedMs: 0, started: false });
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.board.deck.length;
}

function containsMatched(state: GameState, index: number): boolean {
  return state.matched.includes(index);
}

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.board.deck.length || isWon(state)) return state;
  if (state.selection.kind === 'mismatch' || containsMatched(state, index)) return state;
  if (state.selection.kind === 'closed') {
    return Object.freeze({ ...state, selection: Object.freeze({ kind: 'one', index }), started: true });
  }
  const { index: first } = state.selection;
  if (first === index) return state;
  const moves = Math.min(MAX_MOVES, state.moves + 1);
  if (state.board.deck[first] === state.board.deck[index]) {
    return Object.freeze({
      ...state,
      matched: Object.freeze([...state.matched, first, index]),
      selection: CLOSED,
      moves,
    });
  }
  return Object.freeze({
    ...state,
    selection: Object.freeze({ kind: 'mismatch', first, second: index, remainingMs: MISMATCH_DURATION_MS }),
    moves,
  });
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0 || isWon(state) || !state.started) return state;
  const delta = Math.floor(milliseconds);
  if (delta <= 0) return state;
  const elapsedMs = state.elapsedMs + Math.min(delta, MAX_ELAPSED_MS - state.elapsedMs);
  if (state.selection.kind !== 'mismatch') return Object.freeze({ ...state, elapsedMs });
  const remainingMs = state.selection.remainingMs - delta;
  if (remainingMs <= 0) return Object.freeze({ ...state, elapsedMs, selection: CLOSED });
  return Object.freeze({ ...state, elapsedMs, selection: Object.freeze({ ...state.selection, remainingMs }) });
}

