import { useCallback, useEffect, useRef, useState } from 'react';
import { BOARD_SIZES, MAX_BOARD_SEED, type BoardSize } from '../constants.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { activateCard, advanceGame, createGame, isWon } from '../transitions.ts';
import type { GameState } from '../types.ts';
import { formatElapsedTime } from './formatTime.ts';
import { readPreferences, writePreferences, type SessionPreferences } from './storage.ts';

export type SessionAnnouncement = Readonly<{ id: number; text: string }>;
export type GameSession = Readonly<{
  state: GameState;
  paused: boolean;
  revision: number;
  best: number | null;
  celebration: boolean;
  announcement: SessionAnnouncement | null;
  loadStatus: string;
  activateCard: (index: number) => void;
  newGame: () => void;
  restart: () => void;
  changeSize: (size: number) => void;
  loadBoard: (draft: string) => boolean;
  loadSnapshot: (draft: string) => boolean;
  exportSnapshot: () => string;
  resume: () => void;
}>;

function isBoardSize(value: number): value is BoardSize {
  return BOARD_SIZES.some((size) => size === value);
}

function freshBoardCode(size: BoardSize, currentCode?: string): string {
  let seed: number;
  try {
    const values = new Uint32Array(1);
    window.crypto.getRandomValues(values);
    seed = ((values[0] ?? 0) % MAX_BOARD_SEED) + 1;
  } catch {
    seed = (Date.now() % MAX_BOARD_SEED) + 1;
  }
  let code = `np1-${size}-${seed}`;
  if (code === currentCode) {
    seed = seed === MAX_BOARD_SEED ? 1 : seed + 1;
    code = `np1-${size}-${seed}`;
  }
  return code;
}

function initialGame(size: BoardSize): GameState {
  const game = createGame(freshBoardCode(size));
  if (game === null) throw new Error('Could not create an initial game.');
  return game;
}

function announcementForTurn(previous: GameState, next: GameState): string {
  if (next.matched.length > previous.matched.length) {
    if (isWon(next)) {
      return `Pair found. All pairs found in ${next.moves} moves and ${formatElapsedTime(next.elapsedMs)}.`;
    }
    const pairs = next.matched.length / 2;
    return `Pair found. ${pairs} ${pairs === 1 ? 'pair' : 'pairs'} matched.`;
  }
  return 'No match. Cards close after a short pause.';
}

export function useGameSession(): GameSession {
  const [preferences, setPreferences] = useState<SessionPreferences>(readPreferences);
  const [state, setState] = useState<GameState>(() => initialGame(preferences.size));
  const [paused, setPaused] = useState(false);
  const [revision, setRevision] = useState(0);
  const [celebration, setCelebration] = useState(false);
  const [announcement, setAnnouncement] = useState<SessionAnnouncement | null>(null);
  const [loadStatus, setLoadStatus] = useState('');
  const [pageVisible, setPageVisible] = useState(() =>
    typeof document === 'undefined' || document.visibilityState !== 'hidden',
  );
