  const generationRef = useRef(0);
  const announcementIdRef = useRef(0);
  const flushRef = useRef<(now: number) => void>(() => undefined);

  preferencesRef.current = preferences;
  pausedRef.current = paused;
  visibleRef.current = pageVisible;

  const flushAt = (now: number): void => {
    const current = gameRef.current;
    if (!visibleRef.current || pausedRef.current || !current.started || isWon(current)) {
      activeAtRef.current = null;
      return;
    }
    const previousTime = activeAtRef.current;
    activeAtRef.current = now;
    if (previousTime === null) return;
    const advanced = advanceGame(current, now - previousTime);
    if (advanced !== current) {
      gameRef.current = advanced;
      setState(advanced);
    }
  };
  flushRef.current = flushAt;

  const notify = useCallback((text: string): void => {
    announcementIdRef.current += 1;
    setAnnouncement({ id: announcementIdRef.current, text });
  }, []);

  const persist = useCallback((next: SessionPreferences): void => {
    preferencesRef.current = next;
    setPreferences(next);
    writePreferences(next);
  }, []);

  const setPause = useCallback((next: boolean): void => {
    pausedRef.current = next;
    setPaused(next);
  }, []);

  const replaceGame = useCallback((next: GameState, pauseForResume: boolean): void => {
    generationRef.current += 1;
    activeAtRef.current = null;
    gameRef.current = next;
    setState(next);
    setPause(pauseForResume);
    setRevision((current) => current + 1);
    setCelebration(false);
