    flushRef.current(now);
    const previous = gameRef.current;
    if (pausedRef.current) return;
    const next = activateCard(previous, index);
    if (next === previous) return;
    if (!previous.started && next.started) activeAtRef.current = now;
    gameRef.current = next;
    setState(next);
    if (previous.selection.kind !== 'closed' && previous.selection.kind !== 'mismatch') {
      notify(announcementForTurn(previous, next));
      if (isWon(next)) {
        setCelebration(true);
        const currentBest = preferencesRef.current.bestScores[next.board.size];
        if (currentBest === undefined || next.moves < currentBest) {
