  }, []);

  useEffect(() => () => {
    generationRef.current += 1;
  }, []);

  return {
    state,
    paused,
    revision,
    best: preferences.bestScores[state.board.size] ?? null,
    celebration,
    announcement,
    loadStatus,
    activateCard: activate,
    newGame,
    restart,
    changeSize,
    loadBoard,
    loadSnapshot,
    exportSnapshot,
    resume,
  };
