export function useMismatchTimer(
  selection: Selection,
  running: boolean,
  revision: number,
  generationRef: RefObject<number>,
  turnNumber: number,
  turnNumberRef: RefObject<number>,
  gameRef: RefObject<GameState>,
  flushAt: (now: number) => void,
): void {
