    if (event.key === 'ArrowRight' && current % size < size - 1) target += 1;
    if (event.key === 'ArrowUp' && current >= size) target -= size;
    if (event.key === 'ArrowDown' && current < size * (size - 1)) target += size;
    if (offset !== 0) focusCard(target);
  };

  return (
    <div className="board-scroll" ref={scrollRef} onKeyDown={moveFocus}>
      <div className="memory-board" style={style} aria-label={`${size} by ${size} cards`}>
        {game.board.deck.map((faceId, position) => (
          <Card
            key={position}
            position={position}
            columns={size}
            faceId={faceId}
            visible={revealed.has(position)}
            matched={matched.has(position)}
            blocked={blocked}
            tabIndex={position === tabStop ? 0 : -1}
            onActivate={onActivate}
            onFocus={rememberFocus}
            onRef={(node) => {
              if (node === null) cards.current.delete(position);
              else cards.current.set(position, node);
            }}
          />
        ))}
      </div>
    </div>
  );
}

export const Board = forwardRef<BoardHandle, BoardProps>(function Board(props, ref) {
  return <BoardContent {...props} expose={ref} />;
});
import type { MouseEventHandler } from 'react';
import { Face } from './Face.tsx';

export type CardProps = Readonly<{
  position: number;
  columns: number;
  faceId: number;
  visible: boolean;
  matched: boolean;
  blocked: boolean;
  tabIndex: 0 | -1;
  onActivate: (position: number) => void;
  onFocus: MouseEventHandler<HTMLButtonElement>;
  onRef: (node: HTMLButtonElement | null) => void;
}>;

export function Card({ position, columns, faceId, visible, matched, blocked, tabIndex, onActivate, onFocus, onRef }: CardProps): React.JSX.Element {
  const row = Math.floor(position / columns) + 1;
  const column = (position % columns) + 1;
  const state = matched ? 'matched' : visible ? 'revealed' : 'closed';
  const name = matched || visible
    ? `Row ${row}, column ${column}, ${faceName(faceId)}, ${state}`
    : `Row ${row}, column ${column}, closed`;

  const activate: MouseEventHandler<HTMLButtonElement> = (event) => {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    onActivate(position);
  };
  const classes = ['memory-card', visible || matched ? 'memory-card--face' : 'memory-card--back'];
  if (matched) classes.push('memory-card--matched');

  return (
    <button
      ref={onRef}
      className={classes.join(' ')}
      type="button"
      data-position={position}
      aria-label={name}
      aria-disabled={matched || blocked}
      tabIndex={tabIndex}
      onClick={activate}
      onFocus={onFocus}
      style={{ scrollMargin: '6px' }}
    >
      {visible || matched ? <Face id={faceId} /> : <Back />}
      {matched && <span className="card-check" aria-hidden="true">✓</span>}
    </button>
  );
}

function faceName(id: number): string {
