test('initial focus stays put and card activation keys share one button action', async ({ page }) => {
  await page.goto('/');
  await expect(page.locator('body')).toBeFocused();
  const first = page.locator('.memory-card').nth(0);
  await first.focus();
  for (const key of ['Shift+Enter', 'Control+Enter', 'Alt+Enter', 'Meta+Enter', 'Shift+Space', 'Control+Space']) {
    await page.keyboard.press(key);
    await expect(first).toHaveAttribute('aria-label', /closed$/);
  }
  await page.keyboard.press('Enter');
  await expect(first).toHaveAttribute('aria-label', /revealed$/);
  await page.keyboard.press('Space');
  await expect(page.getByText('Moves: 0')).toBeVisible();
  await page.keyboard.press('ArrowRight');
  await expect(page.locator('.memory-card').nth(1)).toBeFocused();
  await page.keyboard.press('Shift+ArrowRight');
  await expect(page.locator('.memory-card').nth(1)).toBeFocused();
  await page.keyboard.press('Tab');
  await expect(page.locator('summary')).toBeFocused();
});

test('hover, pointer cancellation, and the native context menu do not reveal cards', async ({ page }) => {
  await page.goto('/');
  const first = page.locator('.memory-card').first();
  await first.hover();
  await expect(first).toHaveAttribute('aria-label', /closed$/);
  await first.dispatchEvent('pointercancel');
  await first.click({ button: 'right' });
  await expect(first).toHaveAttribute('aria-label', /closed$/);
  await expect(page.getByText('Moves: 0')).toBeVisible();
});

import { expect, test } from '@playwright/test';
import { freezePageClock, loadSnapshot, onePairRemainingSnapshot } from './helpers.ts';

test('every supported board size completes its resumed final match', async ({ page }) => {
  await freezePageClock(page);
  await page.goto('/');
  for (const side of [4, 6, 8, 10, 12, 14, 16]) {
    const pairs = (side * side) / 2;
    const progress = onePairRemainingSnapshot(`np1-${side}-1`, pairs - 1);
    await loadSnapshot(page, progress.json);
    await page.getByRole('button', { name: 'Resume', exact: true }).click();
    await page.locator('.memory-card').nth(progress.second).click();
    await expect(page.getByRole('heading', { name: 'Every pair found' })).toBeVisible();
    await expect(page.getByText(`Pairs: ${pairs}/${pairs}`)).toBeVisible();
    await expect(page.getByText(`Moves: ${pairs}`)).toBeVisible();
  }
});

